input.query:
SELECT * FROM premium_txn WHERE term_id IN (SELECT term_id FROM premium_txn LIMIT 3) ORDER BY term_id, booked_date;
SELECT * FROM claim WHERE claim_id IN (SELECT claim_id FROM claim_txn GROUP BY claim_id HAVING COUNT(*)>=4 LIMIT 2);
SELECT c.claim_id, t.txn_date, t.txn_type, t.cost_type, t.amount FROM claim_txn t JOIN claim c USING(claim_id) WHERE c.claim_id IN (SELECT claim_id FROM claim_txn GROUP BY claim_id HAVING COUNT(*)>=4 LIMIT 2) ORDER BY 1,2;
